text:
#horizontal-before {
  display: grid;
  grid-template-columns: minmax(auto, var(--splitter1-width)) 0 auto;
  width: 500px;
  height: 100px;
  --splitter1-width: 200px;
  position: absolute;
  top: 0;
  left: 0;
}

#horizontal-after {
  display: grid;
  grid-template-columns: auto 0 minmax(auto, var(--splitter2-width));
  width: 500px;
  height: 100px;
  --splitter2-width: 200px;
  position: absolute;
  top: 110px;
  left: 0;
}

#vertical-before {
  display: inline-grid;
  grid-template-rows: minmax(auto, var(--splitter3-height)) 0 auto;
  width: 100px;
  height: 500px;
  --splitter3-height: 200px;
}

#vertical-after {
  display: inline-grid;
  grid-template-rows: auto 0 minmax(auto, var(--splitter4-height));
  width: 100px;
  height: 500px;
  --splitter4-height: 200px;
}

#vertical-splitters {
  display: flex;
  position: absolute;
  top: 0;
  left: 520px;
}
